713→		return nil
714→	}
715→
716→	// Ensure .entire directory exists
717→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
718→		return fmt.Errorf("failed to create .entire directory: %w", err)
719→	}
720→
721→	// Append missing entries to gitignore
