727→
728→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
729→		return fmt.Errorf("failed to write gitignore: %w", err)
730→	}
731→	return nil
732→}
